package pipeline

import (
	"bytes"
	"encoding/json"
)

// Authors need evidence and semantic limits, not acquisition bookkeeping.
// Snapshot before redacting: both independent reviewers retain the original.
func publicationHandoff(h *ResearchHandoff) (*ResearchHandoff, error) {
	if h == nil {
		return nil, nil
	}
	raw, err := json.Marshal(h)
	if err != nil {
		return nil, err
	}
	var out ResearchHandoff
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.UseNumber()
	if err := decoder.Decode(&out); err != nil {
		return nil, err
	}
	for i := range out.Sources {
		source := &out.Sources[i]
		source.ContentSHA256, source.ClaimSHA256, source.EvidenceSHA256, source.SourceSHA256 = "", "", "", ""
		source.ClaimHashes = nil
		removeAcquisitionMetadata(source.SourceContext)
	}
	for i := range out.Claims {
		if source, ok := out.Claims[i].ResearchContext["source_context"].(map[string]any); ok {
			removeAcquisitionMetadata(source)
		}
	}
	removeAcquisitionMetadata(out.EditorialContext)
	return &out, nil
}

func removeAcquisitionMetadata(data map[string]any) {
	// Exact audit keys only. Publication dates, unknown fields, limitations,
	// samples, counterevidence and temporal qualifications are not redacted.
	for _, key := range []string{"fetched_at", "source_file_sha256", "article_text_sha256", "article_text_length", "pagination_complete", "metadata_basis"} {
		delete(data, key)
	}
}

const publicationAuthorInstruction = "\nГРАНИЦА АВТОРСКОГО ТЕКСТА: handoff содержит проверенные утверждения и рабочий контекст редакции. В статью переходят правила, действия, ограничения и ответы на вопросы читателя. Даты получения снимка, устройство проверки, служебные ID, степень уверенности как ярлык и перечни того, чего исследователь не нашёл, остаются за кулисами. Не оправдывай перед читателем источник, краткость или неполноту исследования. " +
	"Если нужен архивный контекст, передай его одной короткой рамкой рядом с датами или в названии; не добавляй вступительный дисклеймер об историчности, подтверждениях и текущей применимости. Анонсированное расписание выражай согласованно как расписание, например через начало и окончание, без утверждения о наблюдавшемся исходе. Даты и условия сами несут нужную границу. " +
	"Сохраняй статус анонса и во вступлении о появлении режима, запуске события или изменении правил. Архивная шапка сама не доказывает, что объявленное событие уже состоялось. Не превращай объявленную возможность в завершённое возвращение, запуск или изменение без evidence результата. Передай её естественным описанием объявленных правил или возможного действия, либо локальной атрибуцией; не добавляй ради этого служебный дисклеймер. " +
	"Оговорка нужна в тексте, когда меняет решение читателя, сохраняет условие, исключение, уверенность или явно требуется brief. Такие оговорки сохраняй полностью. Не заменяй их универсальной страховкой о нехватке сведений. Ссылку на источник вплети в изложение или поставь в конце; не начинай с описания исследовательской процедуры. " +
	"Проверяй и добавленные тобой обобщающие названия: формат, режим, набор, класс, ресурс и подобные слова. Верный перечень объектов не разрешает менять их категорию общим существительным. Если обобщение неточно, сохрани сами объекты и связь между ними, убрав или уточнив только ошибочный классификатор. Внутри одной фразы не объясняй одну и ту же операцию дважды: убери повторную часть, сохранив все разные условия, участников, порядок и сроки. " +
	"Сначала свяжи вопросы читателя с ответами из claims, затем выстрой порядок действий. Начни с сути и практической задачи. Перед выдачей внутренне прочитай весь текст: удали повторное объяснение той же цены, срока или ограничения, сохранив все различные условия и удачные абзацы. Не выводи этот внутренний аудит в статью."

func publicationCriticInstruction(mode string) string {
	if mode != "reconstruct" {
		return ""
	}
	return "\nКАЛИБРОВКА КРИТИКА НОВОГО МАТЕРИАЛА: проверь весь candidate и все необходимые рамки в контексте. Фактическую претензию обоснуй дословным спорным фрагментом и конкретным расхождением с evidence; не приписывай фразе более сильное утверждение, которого она в контексте не делает. Ссылка на опубликованное расписание рядом с датами сохраняет статус анонса; само прошедшее время или слова о плане не доказывают состоявшийся исход либо отмену. Реальное превращение плана в подтверждённый результат, потеря условия, исключения или уверенности по-прежнему требует repair/reject. " +
		"Перечисление подтверждённых источником вариантов или наград не становится исчерпывающим утверждением только из-за их числа: проверь, заявляет ли автор отсутствие других. Не требуй отдельного подтверждения обычной группировки, порядка объяснения или точного арифметического сопоставления уже подтверждённых величин; дополнительные игровые свойства, причинность, советы, неверные расчёты и неподтверждённые выводы всё равно запрещены. " +
		"Проверь также добавленные обобщающие существительные: верно названные объекты могут быть ошибочно отнесены к одному набору, формату, режиму, классу или ресурсу. Требуй локальную правку только при изменении категории или смысла; процитируй спорный классификатор и объясни расхождение с объектом в evidence. Нейтральное обобщение или равноценный термин не требуют ремонта. Если одна операция повторно объяснена внутри той же фразы без нового условия, участника, порядка или срока, укажи только избыточную часть; не удаляй разные условия и полезные соседние абзацы. " +
		"Разделяй необходимую правку и равноценное предпочтение. Для warning, который требует ремонта, назови точное место и конкретную трудность: ошибочное решение, двусмысленный референт, потерянная связь, тяжёлый синтаксис или лишний служебный абзац. Отсутствие предложенного тобой синонима, более короткой фразы либо иной границы абзаца само по себе не основание отказа; это info. Не требуй дисклеймер о текущем состоянии игры, если brief архивный и его рамка уже ясна. " +
		"Отдельно проверь служебные оговорки во вступлении и заключении. Датировка или короткая архивная метка допустима. Рассуждения о том, что источник не подтверждает нынешнюю игру, чего исследователь не нашёл, как он проверял материал и почему нельзя ему доверять вне этих рамок, не отвечают на игровой вопрос. Если brief не требует такого аудита и временной статус можно сохранить короткой датировкой/атрибуцией, это обязательное литературное finding: удали только служебное объяснение, сохрани фактическую рамку, ссылки и читательские условия. Наличие такого текста не оправдывается самим ярлыком «архивный» и не требует добавления новых дисклеймеров. " +
		"За один проход назови все действительно обязательные смысловые и литературные исправления, включая ненужный служебный текст и дубли. После ремонта снова проверь весь материал, но не превращай прежнее необязательное предпочтение в новый запрет без конкретного нового основания. При сохранённых фактах и ясном пригодном тексте верни accept, оставив необязательные предложения как info. Неподтверждённые факты, неполная проверка или реальная трудность читателя не становятся допустимыми из-за лимита ремонтов."
}
